#!/usr/bin/env python3
import sys, json, zlib, struct

MEAN = 0.1307
STD = 0.3081

def load_weights(path):
    with open(path) as f:
        return json.load(f)

def paeth(a, b, c):
    p = a + b - c
    pa = abs(p - a); pb = abs(p - b); pc = abs(p - c)
    if pa <= pb and pa <= pc:
        return a
    elif pb <= pc:
        return b
    return c

def unfilter(bpp, height, stride, data):
    out = bytearray()
    prev = bytearray(stride)
    pos = 0
    for y in range(height):
        f = data[pos]; pos += 1
        row = bytearray(data[pos:pos + stride]); pos += stride
        for i in range(stride):
            a = row[i - bpp] if i >= bpp else 0
            b = prev[i]
            c = prev[i - bpp] if i >= bpp else 0
            if f == 1:
                row[i] = (row[i] + a) & 0xff
            elif f == 2:
                row[i] = (row[i] + b) & 0xff
            elif f == 3:
                row[i] = (row[i] + ((a + b) >> 1)) & 0xff
            elif f == 4:
                row[i] = (row[i] + paeth(a, b, c)) & 0xff
        out.extend(row)
        prev = row
    return out

def decode_png(path):
    with open(path, 'rb') as f:
        data = f.read()
    if data[:8] != b'\x89PNG\r\n\x1a\n':
        raise ValueError('not a PNG file')
    pos = 8
    width = height = bitdepth = colortype = None
    idat = bytearray()
    palette = None
    while pos < len(data):
        length = struct.unpack('>I', data[pos:pos + 4])[0]
        ctype = data[pos + 4:pos + 8].decode('latin1')
        cdata = data[pos + 8:pos + 8 + length]
        if ctype == 'IHDR':
            width, height = struct.unpack('>II', cdata[0:8])
            bitdepth = cdata[8]
            colortype = cdata[9]
        elif ctype == 'PLTE':
            palette = cdata
        elif ctype == 'IDAT':
            idat.extend(cdata)
        elif ctype == 'IEND':
            break
        pos += 12 + length
    if colortype not in (0, 2, 3, 4, 6) or bitdepth != 8:
        raise ValueError('unsupported PNG format')
    channels = {0: 1, 2: 3, 3: 1, 4: 2, 6: 4}[colortype]
    stride = width * channels
    raw = zlib.decompress(bytes(idat))
    pixels = unfilter(channels, height, stride, raw)
    gray = [0.0] * (width * height)
    for y in range(height):
        base = y * stride
        for x in range(width):
            off = base + x * channels
            if colortype == 0 or colortype == 4:
                v = pixels[off]
            elif colortype == 2 or colortype == 6:
                r = pixels[off]; g = pixels[off + 1]; b = pixels[off + 2]
                v = int(0.299 * r + 0.587 * g + 0.114 * b)
            else:
                v = palette[pixels[off] * 3]
            gray[y * width + x] = float(v)
    return width, height, gray

def resize(gray, w, h, tw=28, th=28):
    if w == tw and h == th:
        return gray
    out = [0.0] * (tw * th)
    for ty in range(th):
        sy = (ty + 0.5) * h / th - 0.5
        y0 = max(0, min(h - 1, int(sy))); y1 = min(h - 1, y0 + 1)
        fy = sy - y0
        for tx in range(tw):
            sx = (tx + 0.5) * w / tw - 0.5
            x0 = max(0, min(w - 1, int(sx))); x1 = min(w - 1, x0 + 1)
            fx = sx - x0
            v00 = gray[y0 * w + x0]; v01 = gray[y0 * w + x1]
            v10 = gray[y1 * w + x0]; v11 = gray[y1 * w + x1]
            out[ty * tw + tx] = (v00 * (1 - fx) * (1 - fy) + v01 * fx * (1 - fy)
                              + v10 * (1 - fx) * fy + v11 * fx * fy)
    return out

def matvec(W, b, shape, x):
    odim, idim = shape
    out = [0.0] * odim
    for i in range(odim):
        s = b[i]; base = i * idim
        for j in range(idim):
            s += W[base + j] * x[j]
        out[i] = s
    return out

def main():
    if len(sys.argv) != 3:
        sys.stderr.write('usage: cli_tool weights.json image.png\n')
        sys.exit(1)
    w = load_weights(sys.argv[1])
    ww, hh, gray = decode_png(sys.argv[2])
    img = resize(gray, ww, hh, 28, 28)
    x = [(p / 255.0 - MEAN) / STD for p in img]
    h1 = matvec(w['input_layer.weight']['data'], w['input_layer.bias']['data'], w['input_layer.weight']['shape'], x)
    h1 = [max(0.0, v) for v in h1]
    h2 = matvec(w['hidden_layer.weight']['data'], w['hidden_layer.bias']['data'], w['hidden_layer.weight']['shape'], h1)
    h2 = [max(0.0, v) for v in h2]
    o = matvec(w['output_layer.weight']['data'], w['output_layer.bias']['data'], w['output_layer.weight']['shape'], h2)
    pred = max(range(10), key=lambda i: o[i])
    print(pred)
    with open('/app/prediction.txt', 'w') as f:
        f.write(str(pred))

if __name__ == '__main__':
    main()
